    // Branch at a loose line end if there is one (follows the path), else at the first open edge.
    let pick = -1;
    for (let d = 0; d < g.dotEdges.length && pick < 0; d++) {
      let on = 0, cand = -1;
      for (const x of g.dotEdges[d]) { if (s.e[x] === 1) on++; else if (s.e[x] === -1 && cand < 0) cand = x; }
      if (on === 1 && cand >= 0) pick = cand;
    }
    if (pick < 0) for (let i = 0; i < g.edgeCount; i++) if (s.e[i] === -1) { pick = i; break; }
    if (pick < 0) return; // nothing left and no loop: not a solution
